-- Share of NULL values in every column of the DPD tables (lookup tables excluded).
-- A NULL means the DPD left the field blank, usually because it does not apply
-- (no French name distinct from the English, no suite number, no lot number).
-- SQLite cannot loop over columns in SQL, so each column has its own line.
WITH counts AS (
SELECT 'drug' AS table_name, 'extract' AS column_name, COUNT(*) AS n_rows, SUM("extract" IS NULL) AS n_null FROM "drug"
UNION ALL SELECT 'drug' AS table_name, 'drug_code' AS column_name, COUNT(*) AS n_rows, SUM("drug_code" IS NULL) AS n_null FROM "drug"
UNION ALL SELECT 'drug' AS table_name, 'product_categorization' AS column_name, COUNT(*) AS n_rows, SUM("product_categorization" IS NULL) AS n_null FROM "drug"
UNION ALL SELECT 'drug' AS table_name, 'class' AS column_name, COUNT(*) AS n_rows, SUM("class" IS NULL) AS n_null FROM "drug"
UNION ALL SELECT 'drug' AS table_name, 'din' AS column_name, COUNT(*) AS n_rows, SUM("din" IS NULL) AS n_null FROM "drug"
UNION ALL SELECT 'drug' AS table_name, 'brand_name' AS column_name, COUNT(*) AS n_rows, SUM("brand_name" IS NULL) AS n_null FROM "drug"
UNION ALL SELECT 'drug' AS table_name, 'descriptor' AS column_name, COUNT(*) AS n_rows, SUM("descriptor" IS NULL) AS n_null FROM "drug"
UNION ALL SELECT 'drug' AS table_name, 'pediatric_flag' AS column_name, COUNT(*) AS n_rows, SUM("pediatric_flag" IS NULL) AS n_null FROM "drug"
