UNION ALL SELECT 'drug' AS table_name, 'ai_group_no' AS column_name, COUNT(*) AS n_rows, SUM("ai_group_no" IS NULL) AS n_null FROM "drug"
UNION ALL SELECT 'drug' AS table_name, 'class_f' AS column_name, COUNT(*) AS n_rows, SUM("class_f" IS NULL) AS n_null FROM "drug"
UNION ALL SELECT 'drug' AS table_name, 'brand_name_f' AS column_name, COUNT(*) AS n_rows, SUM("brand_name_f" IS NULL) AS n_null FROM "drug"
UNION ALL SELECT 'drug' AS table_name, 'descriptor_f' AS column_name, COUNT(*) AS n_rows, SUM("descriptor_f" IS NULL) AS n_null FROM "drug"
