UNION ALL SELECT 'status' AS table_name, 'extract' AS column_name, COUNT(*) AS n_rows, SUM("extract" IS NULL) AS n_null FROM "status"
UNION ALL SELECT 'status' AS table_name, 'drug_code' AS column_name, COUNT(*) AS n_rows, SUM("drug_code" IS NULL) AS n_null FROM "status"
