UNION ALL SELECT 'status' AS table_name, 'expiration_date' AS column_name, COUNT(*) AS n_rows, SUM("expiration_date" IS NULL) AS n_null FROM "status"
UNION ALL SELECT 'therapeutic_class' AS table_name, 'extract' AS column_name, COUNT(*) AS n_rows, SUM("extract" IS NULL) AS n_null FROM "therapeutic_class"
UNION ALL SELECT 'therapeutic_class' AS table_name, 'drug_code' AS column_name, COUNT(*) AS n_rows, SUM("drug_code" IS NULL) AS n_null FROM "therapeutic_class"
UNION ALL SELECT 'therapeutic_class' AS table_name, 'tc_atc_number' AS column_name, COUNT(*) AS n_rows, SUM("tc_atc_number" IS NULL) AS n_null FROM "therapeutic_class"
